var root=UnityEngine.GameObject.Find("FPSWorld");var rows=new System.Collections.Generic.List<object>();foreach(UnityEngine.Transform t in root.transform){var renderers=t.GetComponentsInChildren<UnityEngine.Renderer>();var b=new UnityEngine.Bounds();bool first=true;int enabled=0;foreach(var r in renderers){if(first){b=r.bounds;first=false;}else b.Encapsulate(r.bounds);if(r.enabled)enabled++;}rows.Add(new{name=t.name,active=t.gameObject.activeInHierarchy,position=t.position.ToString("F4"),rotation=t.eulerAngles.ToString("F4"),scale=t.lossyScale.ToString("F4"),mesh=renderers.Length,enabled,boundsCenter=b.center.ToString("F4"),boundsSize=b.size.ToString("F4")});}return rows;